function validate(input) {
  const [{ transactions = [] }] = input;
  const ids = new Set();
  for (const [id, amount, day] of transactions) {
    if (id === null || amount === null || day === null) return 'No value in transactions may be null.';
    if (ids.has(id)) return `transaction_id ${id} appears twice.`;
    ids.add(id);
    if (amount <= 0) return `amount ${amount} must be positive.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `transaction_date ${day} must look like 2024-07-01.`;
  }
  return null;
}

