function generate(rand, size) {
  const pad = n => String(n).padStart(2, '0');
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  const days = small ? ['2024-07-01', '2024-07-02', '2024-07-03', '2024-06-30'] : Array.from({ length: 400 }, (_, i) => { const d = new Date(Date.UTC(2023, 0, 1 + i)); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`; });
  const amounts = [1, 2, 50, 75, 120, 150, 200, 300, 999];
  const transactions = [];
  for (let i = 0; i < count; i++) {
    const amount = small ? amounts[Math.floor(rand() * amounts.length)] : 1 + Math.floor(rand() * 100000);
    transactions.push([small ? i + 1 : 5 + i * 2, amount, days[Math.floor(rand() * days.length)]]);
  }
  for (let i = transactions.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [transactions[i], transactions[j]] = [transactions[j], transactions[i]]; }
  return [{ transactions }];
}
